      [x + ux * size, y + uy * size],
      [x - ux * size * 0.55 + px * size * 0.62, y - uy * size * 0.55 + py * size * 0.62],
      [x - ux * size * 0.55 - px * size * 0.62, y - uy * size * 0.55 - py * size * 0.62]
    ];
    return g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
      .fill({ color: color, opacity: opacity == null ? 1 : opacity }).stroke('none');
  }

  // line with a mid-line arrowhead showing propagation direction
  function ray(g, x1, y1, x2, y2, o) {
    o = o || {};
    var gg = g.group();
    var ln = gg.line(x1, y1, x2, y2).stroke({
      color: o.color || TEAL, width: o.width || 2.8, linecap: 'round',
      opacity: o.opacity == null ? 1 : o.opacity
    });
    if (o.dash) ln.attr('stroke-dasharray', o.dash);
    var t = o.at == null ? 0.55 : o.at;
    var mx = x1 + (x2 - x1) * t, my = y1 + (y2 - y1) * t;
    var ang = deg(Math.atan2(y2 - y1, x2 - x1));
    if (!o.noArrow) arrowHead(gg, mx, my, ang, o.head || 8, o.color || TEAL, o.opacity == null ? 1 : o.opacity);
    if (o.tip) {
      var ang2 = ang;
      arrowHead(gg, x2, y2, ang2, o.head || 8, o.color || TEAL, o.opacity == null ? 1 : o.opacity);
    }
    if (o.tip_only) { }
    return gg;
  }

  function leader(g, x1, y1, cxp, cyp, x2, y2, size) {
    var gg = g.group();
    gg.path('M' + x1 + ' ' + y1 + ' Q' + cxp + ' ' + cyp + ' ' + x2 + ' ' + y2)
      .fill('none').stroke({ color: '#111', width: 1.4, linecap: 'round' });
    var ang = deg(Math.atan2(y2 - cyp, x2 - cxp));
    arrowHead(gg, x2, y2, ang, size || 6, '#111', 1);
    return gg;
  }

  function hoverable(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () { showPopup(title, body); });
  }

  function mediumRect(g, x, y, w, h) {
    var grad = draw.gradient('linear', function (add) {
      add.stop(0, '#a6c4d7');
      add.stop(0.45, '#cfe2ec');
      add.stop(0.72, '#f3f8fb');
      add.stop(1, '#c6dbe7');
    }).from(0, 0).to(1, 0);
    return g.rect(w, h).move(x, y).fill(grad).stroke({ color: EDGE, width: 1.2 });
  }

  /* ---------- physics ---------- */
  function optics(theta1, ratio) {
    var tc = deg(Math.asin(Math.min(0.999999, ratio)));
    var s2 = Math.sin(rad(theta1)) / ratio;
    var t2 = (s2 <= 1) ? deg(Math.asin(s2)) : null;
    var R = 1, T = 0;
    if (t2 !== null) {
      var c1 = Math.cos(rad(theta1)), c2 = Math.cos(rad(t2));
      var rs = (c1 - ratio * c2) / (c1 + ratio * c2);
      var rp = (ratio * c1 - c2) / (ratio * c1 + c2);
      R = (rs * rs + rp * rp) / 2;
      T = 1 - R;
    }
    return { tc: tc, t2: t2, R: R, T: T, tir: t2 === null };
  }

  /* ---------- interactive single-boundary view ---------- */
  function renderInteractive() {
    var g = draw.group();
    var y0 = 200, xL = 58, xR = 924, bot = 352, cx = 440;
    var o = optics(state.theta1, state.ratio);
    var t1 = state.theta1, tc = o.tc, t2 = o.t2;

    var rect = mediumRect(g, xL, y0, xR - xL, bot - y0);
    hoverable(rect, 'n\u2081 — the denser medium light starts in',
      'Denser medium n\u2081',
      'The light travels inside this medium. Because n\u2081 > n\u2082, a ray leaving it is bent away from the normal, so there is an incident angle beyond which no refracted ray can exist.');

    // upper region hit area
    var upper = g.rect(xR - xL, y0 - 40).move(xL, 40).fill('#fff').opacity(0.001);
    hoverable(upper, 'n\u2082 — the less dense medium outside',
      'Less dense medium n\u2082',
      'Light can only escape here if Snell\u2019s law has a solution: sin\u03B8\u2082 = (n\u2081/n\u2082)\u00B7sin\u03B8\u2081 \u2264 1.');

    g.line(xL, y0, xR, y0).stroke({ color: EDGE, width: 1.4 });

    // normal
    g.line(cx, 52, cx, 348).stroke({ color: '#444', width: 1.4 }).attr('stroke-dasharray', '9,6');

    txt(g, 108, 104, 'n\u2082', { family: SERIF, italic: true, size: 20 });
    txt(g, 858, 246, 'n\u2081', { family: SERIF, italic: true, size: 20 });

    var L = 145, Lr = 170;
    var s1 = Math.sin(rad(t1)), c1 = Math.cos(rad(t1));
    var Ax = cx - L * s1, Ay = y0 + L * c1;      // incident start (lower left)
    var Bx = cx + L * s1, By = y0 + L * c1;      // reflected end (lower right)

    // dashed critical-angle reference ray (lower-left)
    var sc = Math.sin(rad(tc)), cc = Math.cos(rad(tc));
    var Cx = cx - (L + 8) * sc, Cy = y0 + (L + 8) * cc;
    var dref = ray(g, Cx, Cy, cx, y0, { color: TEAL, width: 2, dash: '8,6', noArrow: true, opacity: 0.85 });
    hoverable(dref, 'Critical-angle reference \u03B8_c = ' + tc.toFixed(1) + '\u00B0',
      'The critical angle \u03B8_c',
      'sin\u03B8_c = n\u2082/n\u2081 = ' + state.ratio.toFixed(2) + ', so \u03B8_c = ' + tc.toFixed(1) + '\u00B0. This dashed ray marks the threshold: inside it light escapes, outside it light is trapped.');

    // refracted ray
    if (!o.tir) {
      var op = 0.22 + 0.78 * Math.max(0, Math.min(1, o.T));
      var Rx = cx + Lr * Math.sin(rad(t2)), Ry = y0 - Lr * Math.cos(rad(t2));
      var rr = ray(g, cx, y0, Rx, Ry, { color: TEAL, width: 2.8, opacity: op, head: 8.5 });
      hoverable(rr, 'Refracted ray — \u03B8\u2082 = ' + t2.toFixed(1) + '\u00B0 (fades as \u03B8\u2081 \u2192 \u03B8_c)',
        'Refracted ray',
        'Snell\u2019s law gives sin\u03B8\u2082 = sin\u03B8\u2081 / (n\u2082/n\u2081). Because n\u2082 < n\u2081 the ray bends away from the normal, and its transmitted share of the energy drops to zero exactly at \u03B8_c.');
      if (t1 > 1.2) {
        arcPath(g, cx, y0, 64, -90, t2 - 90, TEAL, 1.1);
        var am = (-90 + (t2 - 90)) / 2;
        thetaLabel(g, cx + 84 * Math.cos(rad(am)), y0 + 84 * Math.sin(rad(am)), '\u2082', 17);
      }
      // grazing marker
      if (Math.abs(t1 - tc) < 0.6) {
        g.rect(15, 15).move(cx, y0 - 15).fill('none').stroke({ color: '#111', width: 1.4 });
        txt(g, cx + 92, y0 - 28, '\u03B8\u2082 = 90\u00B0', { size: 15, family: SERIF, italic: true });
      }
      txt(g, Math.min(660, Rx + 58), Math.max(30, Ry - 14), 'Refracted ray', { size: 13 });
    } else {
      txt(g, 790, 262, 'Total internal', { size: 15 });
      txt(g, 790, 283, 'reflection', { size: 15 });
    }

    // incident ray
    var ir = ray(g, Ax, Ay, cx, y0, { color: TEAL, width: 2.9, head: 8.5, at: 0.5 });
    hoverable(ir, 'Incident ray — \u03B8\u2081 = ' + t1.toFixed(0) + '\u00B0',
      'Incident ray',
      'The ray travels up through the dense medium and strikes the boundary at \u03B8\u2081 measured from the dashed normal. Everything downstream is decided by how \u03B8\u2081 compares with \u03B8_c.');

    // reflected ray
    var refOp = 0.35 + 0.65 * o.R;
    var rf = ray(g, cx, y0, Bx, By, { color: TEAL, width: 2.2 + 1.5 * o.R, opacity: refOp, head: 8.5, at: 0.6 });
    hoverable(rf, 'Reflected ray — always at \u03B8\u2081 (' + (o.R * 100).toFixed(0) + '% of the light)',
      'Reflected ray',
      'Reflection obeys \u03B8_reflected = \u03B8_incident at every angle. Its share grows from a few percent near normal incidence to 100% once \u03B8\u2081 exceeds \u03B8_c.');

    // arcs for theta1
    if (t1 > 1.2) {
      arcPath(g, cx, y0, 52, 90, 90 + t1, TEAL, 1.1);
      var m1 = 90 + t1 / 2;
      thetaLabel(g, cx + 72 * Math.cos(rad(m1)), y0 + 72 * Math.sin(rad(m1)), '\u2081', 17);
      arcPath(g, cx, y0, 52, 90 - t1, 90, TEAL, 1.1);
      var m2 = 90 - t1 / 2;
      thetaLabel(g, cx + 72 * Math.cos(rad(m2)), y0 + 72 * Math.sin(rad(m2)), '\u2081', 17);
    }
    // arc for theta_c
    arcPath(g, cx, y0, 104, 90, 90 + tc, TEAL, 1.1, '5,4');
    var mc = 90 + tc / 2;
    thetaLabel(g, cx + 124 * Math.cos(rad(mc)), y0 + 124 * Math.sin(rad(mc)), 'c', 16, TEAL);

    // callout labels with leaders
    txt(g, 150, 332, 'Incident ray', { size: 13 });
    leader(g, 150, 320, 190, 296, (Ax + cx) / 2 - 22, (Ay + y0) / 2 + 16, 6);
    txt(g, 700, 336, 'Reflected ray', { size: 13 });
    leader(g, 700, 325, 668, 306, (cx + Bx) / 2 + 16, (y0 + By) / 2 + 14, 6);

    // readout panel
    var rp = g.group();
    rp.rect(238, 96).move(702, 44).fill('#fff').opacity(0.92).stroke({ color: '#c3cdd4', width: 1 }).radius(5);
    var lines = [
      '\u03B8\u2081 = ' + t1.toFixed(0) + '\u00B0',
      '\u03B8\u2082 = ' + (o.tir ? 'none (no escaping ray)' : t2.toFixed(1) + '\u00B0'),
      '\u03B8_c = ' + tc.toFixed(1) + '\u00B0',
      'n\u2082/n\u2081 = ' + state.ratio.toFixed(2)
    ];
    for (var i = 0; i < lines.length; i++) {
      txt(rp, 821, 62 + i * 22, lines[i], { size: 13.5, halo: false, color: i === 1 && o.tir ? '#a33' : '#123' });
    }
    hoverable(rp, 'Live numbers for this configuration',
      'Readout',
      'When sin\u03B8\u2081 exceeds n\u2082/n\u2081 there is no angle \u03B8\u2082 whose sine equals sin\u03B8\u2081\u00B7(n\u2081/n\u2082) \u2014 Snell\u2019s law simply has no solution, which is why the refracted ray disappears.');
  }

  /* ---------- three textbook panels ---------- */
  function panel(px, kind, caption) {
    var g = draw.group();
    var x0 = px + 14, wRect = 282, y0 = 142, bot = 266, cx = px + 152;
    mediumRect(g, x0, y0, wRect, bot - y0);
    g.line(x0, y0, x0 + wRect, y0).stroke({ color: EDGE, width: 1.2 });
    g.line(cx, 52, cx, 252).stroke({ color: '#444', width: 1.3 }).attr('stroke-dasharray', '8,5');
    txt(g, px + 52, 82, 'n\u2082', { family: SERIF, italic: true, size: 17 });
    txt(g, px + 258, 172, 'n\u2081', { family: SERIF, italic: true, size: 17 });

    var tc = deg(Math.asin(Math.min(0.999999, state.ratio)));
    var t1 = kind === 'a' ? tc * 0.72 : (kind === 'b' ? tc : Math.min(82, tc + 20));
    var L = 112;
    var s1 = Math.sin(rad(t1)), c1 = Math.cos(rad(t1));
    var Ax = cx - L * s1, Ay = y0 + L * c1;
    var Bx = cx + L * s1, By = y0 + L * c1;

    ray(g, Ax, Ay, cx, y0, { width: 2.6, head: 7, at: 0.5 });
    ray(g, cx, y0, Bx, By, { width: 2.6, head: 7, at: 0.6 });

    var sub = (kind === 'a' || kind === 'c') ? '\u2081' : 'c';
    arcPath(g, cx, y0, 40, 90, 90 + t1, TEAL, 1);
    arcPath(g, cx, y0, 40, 90 - t1, 90, TEAL, 1);
    var ma = 90 + t1 / 2, mb = 90 - t1 / 2;
    if (kind !== 'c') {
      thetaLabel(g, cx + 58 * Math.cos(rad(ma)), y0 + 58 * Math.sin(rad(ma)), sub, 15);
    }
    thetaLabel(g, cx + 58 * Math.cos(rad(mb)), y0 + 58 * Math.sin(rad(mb)), sub, 15);

    if (kind === 'a') {
      var t2 = deg(Math.asin(Math.sin(rad(t1)) / state.ratio));
      var Rx = cx + 112 * Math.sin(rad(t2)), Ry = y0 - 112 * Math.cos(rad(t2));
      ray(g, cx, y0, Rx, Ry, { width: 2.6, head: 7 });
      arcPath(g, cx, y0, 42, -90, t2 - 90, TEAL, 1);
      var mr = (-90 + (t2 - 90)) / 2;
      thetaLabel(g, cx + 60 * Math.cos(rad(mr)), y0 + 60 * Math.sin(rad(mr)), '\u2082', 15);
      txt(g, px + 148, 20, 'Refracted ray', { size: 12.5 });
      leader(g, px + 168, 29, px + 196, 42, Rx - 14, Ry - 10, 5.5);
      txt(g, px + 52, 124, 'Incident ray', { size: 12.5 });
      leader(g, px + 56, 133, px + 60, 158, (Ax + cx) / 2 - 12, (Ay + y0) / 2 + 8, 5.5);
      txt(g, px + 176, 306, 'Reflected ray', { size: 12.5 });
      leader(g, px + 168, 297, px + 150, 280, (cx + Bx) / 2 + 10, (y0 + By) / 2 + 12, 5.5);
    } else if (kind === 'b') {
      ray(g, cx, y0, cx + 128, y0, { width: 2.6, head: 7, at: 0.65 });
      g.rect(13, 13).move(cx, y0 - 13).fill('none').stroke({ color: '#111', width: 1.3 });
      txt(g, cx + 62, y0 - 26, '\u03B8\u2082 = 90\u00B0', { size: 14, family: SERIF, italic: true });
    } else {
      var Dx = cx - (L + 6) * Math.sin(rad(tc)), Dy = y0 + (L + 6) * Math.cos(rad(tc));
      ray(g, Dx, Dy, cx, y0, { width: 2.2, dash: '8,6', noArrow: true, opacity: 0.9 });
      arcPath(g, cx, y0, 74, 90, 90 + tc, TEAL, 1, '5,4');
      var mc2 = 90 + tc / 2;
      thetaLabel(g, cx + 92 * Math.cos(rad(mc2)), y0 + 92 * Math.sin(rad(mc2)), 'c', 15, TEAL);
      thetaLabel(g, cx + 34, y0 + 26, '\u2081', 15);
      txt(g, px + 232, y0 + 46, 'Total internal', { size: 12.5 });
      txt(g, px + 232, y0 + 63, 'reflection', { size: 12.5 });
    }

    txt(g, cx, 346, caption, { size: 14, halo: false });

    var hit = g.rect(300, 340).move(px, 10).fill('#fff').opacity(0.001);
    var tips = {
      a: ['(a) \u03B8\u2081 < \u03B8_c: part refracts, part reflects', 'Case (a): ordinary refraction',
        'Below the critical angle the boundary splits the light: a refracted ray escapes into n\u2082 bent away from the normal, and a weaker reflected ray stays in n\u2081.'],
      b: ['(b) \u03B8\u2081 = \u03B8_c: refracted ray grazes the surface', 'Case (b): grazing at \u03B8_c',
        'Exactly at the critical angle the refracted ray lies flat along the interface, \u03B8\u2082 = 90\u00B0. This is the definition sin\u03B8_c = n\u2082/n\u2081.'],
      c: ['(c) \u03B8\u2081 > \u03B8_c: total internal reflection', 'Case (c): total internal reflection',
        'Past \u03B8_c Snell\u2019s law has no solution for \u03B8\u2082, so nothing escapes: 100% of the light is reflected back into the dense medium.']
    }[kind];
    hoverable(hit, tips[0], tips[1], tips[2]);
  }

  function renderPanels() {
    panel(4, 'a', '(a)');
    panel(330, 'b', '(b)');
    panel(656, 'c', '(c)');
  }

  /* ---------- render ---------- */
  function render() {
    draw.clear();
    draw.rect(W, H).fill('#fff');
    if (state.panels) renderPanels(); else renderInteractive();
    var o = optics(state.theta1, state.ratio);
    var el = document.getElementById('calcOut');
    if (el) {
      el.innerHTML = '\u03B8\u2081 = ' + state.theta1.toFixed(0) + '\u00B0<br>' +
        '\u03B8\u2082 = ' + (o.tir ? '<span style="color:#a33">none — TIR</span>' : o.t2.toFixed(1) + '\u00B0') + '<br>' +
        '\u03B8_c = ' + o.tc.toFixed(1) + '\u00B0 &nbsp; (sin\u03B8_c = n\u2082/n\u2081 = ' + state.ratio.toFixed(2) + ')';
    }
  }

  /* ---------- interaction handlers ---------- */
  window.update_incidentAngle = function (v) { state.theta1 = v; render(); };
  window.update_indexRatio = function (v) { state.ratio = v; render(); };
  window.toggle_caseView = function (on) { state.panels = !!on; render(); };

  /* ---------- demo steps ---------- */
  var steps = [
    { title: 'Ordinary refraction', narration: 'Light inside the denser medium n\u2081 hits the boundary at a modest angle: part reflects back at \u03B8\u2081 and part refracts into n\u2082, bent away from the normal so \u03B8\u2082 > \u03B8\u2081.', state: { caseView: 'Interactive single boundary', indexRatio: 0.66, incidentAngle: 30 } },
    { title: 'Pushing toward the limit', narration: 'Drag \u03B8\u2081 larger and watch the refracted ray swing rapidly toward the surface while the transmitted ray dims \u2014 \u03B8\u2082 grows much faster than \u03B8\u2081 near the threshold.', state: { incidentAngle: 38 } },
    { title: 'The critical angle', narration: 'At \u03B8\u2081 = \u03B8_c the refracted ray lies flat along the interface: \u03B8\u2082 = 90\u00B0. This is exactly where sin(\u03B8_c) = n\u2082/n\u2081.', state: { incidentAngle: 41 } },
    { title: 'Total internal reflection', narration: 'Past \u03B8_c the refracted ray is gone entirely \u2014 there is no solution for \u03B8\u2082 \u2014 and 100% of the light returns into n\u2081 as the reflected ray.', state: { incidentAngle: 60 } },
    { title: 'Changing the media', narration: 'Now raise the index ratio n\u2082/n\u2081 toward 1: the dashed \u03B8_c reference swings outward and the same 60\u00B0 ray refracts again. Lower the ratio and light is confined at much shallower angles.', state: { indexRatio: 0.95, incidentAngle: 60 } },
    { title: 'Back to the textbook figure', narration: 'Switch to the three-panel view to see cases (a), (b), and (c) side by side \u2014 they are simply \u03B8\u2081 < \u03B8_c, \u03B8\u2081 = \u03B8_c, and \u03B8\u2081 > \u03B8_c for one fixed pair of media.', state: { caseView: 'Three textbook panels (a)(b)(c)', indexRatio: 0.66, incidentAngle: 60 } }
  ];
  var cur = 0;

  function applyState(st) {
    if (st.caseView !== undefined) {
      var on = st.caseView.indexOf('Three') === 0;
      document.getElementById('caseViewInput').checked = on;
      state.panels = on;
    }
    if (st.indexRatio !== undefined) {
      document.getElementById('indexRatioInput').value = st.indexRatio;
      document.getElementById('indexRatioVal').value = (+st.indexRatio).toFixed(2);
      state.ratio = +st.indexRatio;
    }
    if (st.incidentAngle !== undefined) {
      document.getElementById('incidentAngleInput').value = st.incidentAngle;
      document.getElementById('incidentAngleVal').value = st.incidentAngle;
      state.theta1 = +st.incidentAngle;
    }
    render();
  }

  function setStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    applyState(steps[cur].state);
    document.getElementById('demoNarration').innerHTML =
      '<b>' + steps[cur].title + '</b><br>' + steps[cur].narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { setStep(cur + 1); };
  window.prevStep = function () { setStep(cur - 1); };

  setStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

